var page = template.Must(template.ParseFiles("templates/orders.html"))

func orders(w http.ResponseWriter, r *http.Request) {
    rows, err := repo.Orders(r.Context())
    if err != nil {
        http.Error(w, "orders unavailable", http.StatusInternalServerError)
        return
    }
    if err := page.Execute(w, OrdersView{Title: "Orders", Rows: rows}); err != nil {
        log.Printf("render orders: %v", err) // headers may already be sent
    }
}
